        "company": "트위스트 바이오사이언스는 실리콘 칩 위에 DNA를 화학적으로 '인쇄'하듯 합성하는 독자 기술을 가진 회사다. 이렇게 만든 인공 유전자와 항체 조각을 제약회사, 바이오 스타트업, 대학 연구소 등 약 2,650여 고객사에 팔아서 돈을 번다. 최근에는 인공지능(AI)을 이용해 신약 후보물질을 찾는 제약·바이오텍 기업들의 수요가 늘면서 치료제(Therapeutics) 부문 매출이 특히 빠르게 커지고 있다. 암 등을 진단하는 차세대 유전체 분석(NGS, 한 번에 방대한 DNA 서열을 읽어내는 기술) 시장에도 진출해 있어 진단(Diagnostics) 매출도 함께 성장 중이다. 2026 회계연도 3분기까지 14분기 연속 매출 성장을 이어가며 시장의 주목을 받고 있지만, 여전히 영업적자를 내고 있는 성장 초기 단계의 회사이기도 하다.",
        "lead": "트위스트 바이오사이언스(TWST)는 실리콘 칩 위에 DNA를 합성해 유전자·항체·시퀀싱(유전체 서열분석) 부품을 만들어 파는 합성생물학 기업이다. 2026년 8월3일 발표한 3분기(4~6월) 매출이 1억1,838만달러로 전년동기대비 23% 늘며 컨센서스(1억1,454만달러)를 웃돌았고, 14분기 연속 매출 성장을 이어갔다. 회사는 8월19일 FY2026 연간 매출 전망을 기존보다 1,200만달러 높인 4억5,600만~4억5,700만달러로 상향했으며, AI 기반 신약개발 수요에 힘입어 치료제(Therapeutics) 부문 매출은 전년비 49% 늘어난 4,040만달러를 기록했다. 실적 발표 이후 Baird 등 증권사들이 목표주가를 잇달아 올리면서 컨센서스 목표주가도 13% 상승해 104달러가 됐다.",
