        "lead": "타서스 파머슈티컬스는 8월6일 발표한 2026년 2분기 실적에서 엑스뎀비 매출이 1억7,391만2천 달러로 전년동기 대비 69% 넘게 늘었다고 밝히고, 연간 매출 가이던스도 6억8,500만~7억500만 달러로 높였다. 같은 날 망막질환 치료제를 보유한 알케우스 파마슈티컬스를 최대 8억 달러(선불금 4억5,000만 달러)에 인수한다고 발표하며 안과 영역을 넓혔고, 이를 위한 1억2,500만 달러 규모 사모증자(PIPE)는 초과청약으로 마감됐다. 실적과 인수 소식 이후인 8월12일 오펜하이머·미즈호 등이 목표주가를 97~98달러에서 100달러로 올렸지만, 8월17일에는 공매도 업체 컬퍼 리서치가 메디케어 코페이 제도와 시장 규모 과장 의혹을 제기하며 주가가 장중 8% 급락하기도 했다. 이런 호재와 악재가 겹치며 최근 한 달 새 주가가 크게 출렁였다.",
