        "status": "done",
        "company": "GeneDx(진DX 홀딩스)는 원인을 알 수 없는 희귀·소아 질환을 앓는 환자의 DNA 전체를 읽어(전장유전체·엑솜 시퀀싱, Whole Genome/Exome Sequencing) 병을 일으키는 유전자 변이를 찾아주는 유전자 진단 검사 회사다. 돈은 병원·의사가 환자를 위해 의뢰하는 이 유전자 검사료(보험사 지급분 포함)에서 번다. 주 고객은 소아과·유전학과 의사와 병원이며, 최종 수혜자는 진단이 어려운 신생아·어린이 환자들이다. 지금까지 66만 5천 건이 넘는 임상 엑솜·게놈 데이터를 쌓아 세계 최대 규모의 희귀질환 유전체 데이터셋을 보유한 것이 강점이다. 2025년 AI 기반 유전체 해석 회사 Fabric Genomics를 인수하면서 AI 진단 테마로도 묶이기 시작했고, 최근에는 2026년 2분기 실적이 시장 예상을 웃돌고 이사회 멤버·대주주의 대규모 자사주 매수가 겹치며 다시 주목받고 있다.",
