        "lead": "GeneDx(진DX 홀딩스)는 소아·희귀질환 환자의 유전체를 전부 읽어 병의 원인을 찾아주는 유전자 진단 회사다. 2026년 8월 3일 발표한 2분기 매출이 1억1,444만 달러로 전년동기 대비 11.4% 늘며 시장 예상을 웃돌았고, 8월 19일 자 분석에서는 최근 30일간 이번 분기 컨센서스 EPS 전망치가 146.67% 상향된 것으로 나타났다. 같은 시기 이사회 멤버이자 최대 기관투자자인 캐스딘 캐피털(Casdin Capital)의 엘리 캐스딘과 코르벡스(Corvex)의 이사 키스 마이스터가 각각 수백만~수천만 달러어치 자사주를 사들였고, 8월 초에는 블랙스톤 계열사가 참여한 소규모 증자와 함께 2026년 매출 가이던스를 재확인하며 주가가 18.4% 뛰었다. 다만 주가는 여전히 52주 고점 대비 50.75% 낮은 수준이며, 2026년 1분기 실적 부진과 4월 애널리스트 목표주가 대폭 하향, Fabric Genomics 인수를 둘러싼 증권 집단소송이라는 부담도 함께 남아 있다.",
