        "company": "Xometry(조메트리)는 CNC 가공, 3D 프린팅, 판금 가공, 사출 성형 같은 산업용 부품을 필요할 때마다 만들어주는 AI 기반 온라인 장터(마켓플레이스) 회사다. 엔지니어가 설계 파일을 올리면 인공지능이 즉시 견적을 산출하고, 전 세계에 흩어진 수천 개 협력 제조업체 네트워크와 자동으로 연결해 부품을 만들어 배송해준다. 즉 회사가 직접 공장을 소유·운영하는 게 아니라 발주자와 제조업체를 이어주고 그 과정에서 수수료를 받아 돈을 번다. 주요 고객은 자금이 넉넉지 않은 스타트업부터 포춘 100대 산업재·항공우주·방위·의료기기 대기업까지 다양하다. 최근에는 산업 소프트웨어 대기업 지멘스(Siemens)가 2026년 5월 5,000만 달러를 투자하며 자사 설계 소프트웨어에 Xometry의 견적·조달 기능을 결합하는 전략적 제휴를 맺었고, 최근 분기 매출 성장률이 40%를 넘어서면서 시장의 관심이 커지고 있다.",
        "lead": "Xometry는 산업용 부품을 AI로 즉시 견적내고 전 세계 제조업체 네트워크에 발주해주는 온디맨드 제조 마켓플레이스다. 2026년 8월 4일 발표한 2분기 매출이 2억2,928만 달러로 전년 동기 대비 41% 늘며 사상 최대치를 기록했고, 회사는 연간 매출 성장 가이던스를 27~28%에서 33~34%로 상향했다. 앞서 5월 7일에는 지멘스가 5,000만 달러를 투자하며 파트너십을 발표하자 주가가 하루 만에 약 39% 급등했다. 이런 실적과 파트너십을 근거로 JP모건은 8월 24일 목표주가 120달러의 비중확대(Overweight) 의견을 새로 제시했다. 다만 주가는 이미 자체 산정 적정가치 대비 87% 고평가됐다는 평가가 나오고, 최근 24개월간 임원진의 주식 매도가 2,200만 달러를 넘어 밸류에이션 부담과 내부자 매도가 반대 근거로 꼽힌다.",
