        "leadOriginal": "워리어 멧 콜은 미국 앨라배마에서 제철용 석탄(원료탄)을 캐 전 세계 철강회사에 파는 회사다. 8월 5일 발표한 2026년 2분기 실적에서 매출이 5억970만달러로 전년 동기(2억9,750만달러) 대비 71% 늘고, 순이익은 8,740만달러(주당순이익 1.65달러)로 전년(560만달러, 주당 0.11달러)보다 크게 뛰었다. 석탄 1톤당 평균 판매가격도 137.82달러로 6% 올랐고 판매량은 사상 최대인 370만 숏톤(65%↑)을 기록했다. 새 광산 블루크릭 물량에 대한 고객 수요가 강해 회사가 2026년 연간 판매 가이던스를 50만 숏톤 늘리자, 주가는 발표 후 11.5% 뛰며 한때 111.31달러의 사상 최고가를 기록했다. 중국의 원료탄 수입 역시 급증하는 등 국제 수요 자체가 강한 국면이어서 이 종목이 시장의 주목을 받고 있다."
