        "leadOriginal": "가이드와이어는 손해보험사에 계약·청구·보험료 처리 소프트웨어를 클라우드 구독 방식으로 파는 회사로, 최근 실적 성장이 가팔라지며 주가가 강세를 보여왔다. 2026년 2~4월 분기(회계연도 3분기) 매출이 3억7,254만 달러로 전년동기 대비 26.9% 늘었고, 연간반복매출(ARR)은 11억4,700만 달러로 19% 증가했으며 신규 클라우드 계약도 11건 확보했다. 이런 성장세를 반영해 구겐하임은 목표주가를 180달러에서 210달러로, BTIG는 175달러에서 230달러로 각각 올리며 매수 의견을 유지했다. 다만 회사는 오늘 4분기 실적 발표를 앞두고 있는데, Zacks는 어닝 서프라이즈 예측치(Earnings ESP)가 -1.98%로 나타나 이번 분기 실적이 시장 예상치를 넘어서기 어려울 수 있다고 짚었고, 발표 하루 전인 9월2일에는 임원 매도 소식과 겹치며 주가가 4.8% 빠지기도 했다."
